use vstd::prelude::*;

verus! {

// Specification function to define what it means for a vector to be the reverse of a slice
spec fn is_reverse_of(result: Seq<i32>, a: Seq<i32>) -> bool {
    result.len() == a.len() &&
    forall|i: int| 0 <= i < a.len() ==> result[i] == a[a.len() - 1 - i]
}

fn reverse(a: &[i32]) -> (result: Vec<i32>)
    ensures
        result@.len() == a@.len(),
        is_reverse_of(result@, a@),
{
    let mut result = Vec::with_capacity(a.len());
    
    let ghost original_seq = a@;
    
    let mut i: usize = 0;
    
    for &value in a.iter().rev()
        invariant
            i <= a@.len(),
            result@.len() == i,
            forall|j: int| 0 <= j < i ==> result@[j] == original_seq[original_seq.len() - 1 - j],
    {
        result.push(value);
        i = i + 1;
    }
    
    assert(result@.len() == a@.len());
    assert(is_reverse_of(result@, a@));
    
    result
}

} // verus!